/* Sticky на обёртке template-part: внутренняя группа ограничена высотой шапки. */
.wp-site-blocks > header.wp-block-template-part{position:sticky;top:var(--wp-admin--admin-bar--height,0px);z-index:50;background-color:var(--wp--preset--color--base)}

/* Линии только между соседними публикациями, включая добавленные через «Показать ещё». */
.home-publications > .wp-block-post-template > li + li{border-block-start:1px solid var(--wp--preset--color--accent-6);padding-block-start:var(--wp--preset--spacing--16)}

/* Контакты: Bootstrap Fill в штатном Social Icons; круги остаются 24px при наведении. */
