/* Корень даёт подвалу 16px сверху. Поле страницы уже стоит на внутренней группе, второй зазор не нужен. */
.wp-site-blocks > footer.wp-block-template-part{margin-block-start:0}

/* Карточка: дата с заголовком, заголовок с анонсом. Между карточками работает blockGap списка. */
.wp-block-post-template > li > *{margin-block:0}
.wp-block-post-template > li > .wp-block-post-date + .wp-block-post-title{margin-block-start:var(--wp--preset--spacing--8)}
.wp-block-post-template > li > .wp-block-post-title + .wp-block-post-excerpt{margin-block-start:var(--wp--preset--spacing--12)}

/* В записи дата принадлежит заголовку, а не обложке. */
main > .wp-block-post-title{margin-block:0}
main > .wp-block-post-title + .wp-block-post-date{margin-block-start:var(--wp--preset--spacing--8);margin-block-end:0}

/* В статье один зазор на стыке. Перед заголовком больше, чем после. Соседний заголовок берёт свой отступ «до». */
.wp-block-post-content.is-layout-constrained > h2 + *:not(h1, h2, h3, h4, h5, h6){margin-block-start:var(--wp--preset--spacing--12)}
.wp-block-post-content.is-layout-constrained > :is(h3, h4, h5, h6) + *:not(h1, h2, h3, h4, h5, h6){margin-block-start:var(--wp--preset--spacing--8)}
.wp-block-post-content.is-layout-constrained > * + h2{margin-block-start:var(--wp--preset--spacing--32)}
.wp-block-post-content.is-layout-constrained > * + :is(h3, h4, h5, h6){margin-block-start:var(--wp--preset--spacing--24)}
.wp-block-image .wp-element-caption{margin-block:var(--wp--preset--spacing--8) 0}

/* Ссылка плагина — inline, её padding вылезает вверх и съедает зазор. */
.wp-block-query > .wp-block-query-pagination,.wp-block-query > .wp-block-buttons{margin-block-start:var(--wp--preset--spacing--24)}
.wp-load-more__button{display:inline-block}

.wp-block-post-content a:where(:not(.wp-element-button)),
main > p a{text-underline-offset:0.18em}
.wp-block-post-content a:where(:not(.wp-element-button)):hover,
main > p a:hover{color:var(--wp--preset--color--accent-4)}
a:focus-visible{outline:2px solid var(--wp--preset--color--contrast);outline-offset:3px}

/* Комментарии: разделители, компактные ветки и форма без лишней линии в пустом обсуждении. */
.wp-block-comment-template li + li{border-block-start:1px solid var(--wp--preset--color--accent-6);margin-block-start:var(--wp--preset--spacing--16);padding-block-start:var(--wp--preset--spacing--16)}
.wp-block-comment-template .wp-block-avatar:empty{display:none}
.wp-block-comment-template ol{border-inline-start:1px solid var(--wp--preset--color--accent-6);margin-block-start:var(--wp--preset--spacing--16);padding-inline-start:var(--wp--preset--spacing--16)}
.wp-block-post-comments-form > .comment-reply-title{margin-block-start:0}
.wp-block-comments h2 + .wp-block-post-comments-form{border-block-start:0;padding-block-start:0}
@media(max-width:600px){.wp-block-post-comments-form .wp-block-button__link{font-size:var(--wp--preset--font-size--small);padding-inline:var(--wp--preset--spacing--16)}}
